const clean=v=>String(v??"").replace(/\s+/g," ").trim();
const account=()=>{const e=[...document.querySelectorAll("[aria-label]")].find(x=>/Google Account:/i.test(x.getAttribute("aria-label")||""));if(!e)return null;const s=e.getAttribute("aria-label")||"";const m=s.match(/Google Account:\s*(.*?)\s*\(([^)]+@[^)]+)\)/is);return m?{name:clean(m[1]),email:clean(m[2])}:{name:null,email:null};};
window.ox.install(({action})=>{
 action("listSessions",{async invoke(){const deadline=Date.now()+10000;while(Date.now()<deadline){const a=account();if(a?.email){const route=location.pathname.match(/^\/calendar\/u\/\d+\/r/);if(!route)throw new Error('Calendar account route unavailable');return [{id:a.email.toLowerCase(),label:a.email,url:location.origin+route[0]}];}await new Promise(r=>setTimeout(r,150));}if(location.hostname==='accounts.google.com')return [];throw new Error('Calendar account state could not be determined');}});
 action("login",{async invoke(){location.assign('https://calendar.google.com/calendar/u/0/r');return null;}});
 action("getCurrentAccount",{async invoke(){const a=account();if(!a)throw new Error("Google Calendar is not signed in.");return a;}});
 action("listVisibleEvents",{async invoke(){if(!account())throw new Error("Google Calendar is not signed in.");const deadline=Date.now()+10000;while(!document.querySelector('[role="grid"]')&&Date.now()<deadline)await new Promise(r=>setTimeout(r,150));if(!document.querySelector('[role="grid"]'))throw new Error('Calendar grid not ready');const range=(document.title.match(/Google Calendar - (.+)$/)||[])[1]||null;const seen=new Set(),items=[];for(const el of document.querySelectorAll('[data-eventid]')){const label=clean(el.innerText);if(!label||seen.has(label))continue;seen.add(label);const title=clean((el.innerText||'').split('\n')[0]);items.push({title,label});}return {rangeLabel:range,items,nextCursor:null};}});
 action("openCreateEvent",{async invoke(args){const enc=encodeURIComponent;let url="https://calendar.google.com/calendar/u/0/r/eventedit?text="+enc(args.title);if(args.start){const fmt=v=>String(v).replace(/[-:]/g,"").replace(/\.\d{3}/,"");url+="&dates="+enc(fmt(args.start)+(args.end?"/"+fmt(args.end):""));}if(args.details)url+="&details="+enc(args.details);if(args.location)url+="&location="+enc(args.location);return {url};}});
});
